const bodySkillsGames=[
{id:223,type:"Imagen corporal",categories:["Esquema corporal","Juegos motrices","Juegos cooperativos"],title:"La foto corporal",cycle:"1.º ciclo",goals:["Imagen corporal","Atención"],material:"Sin material",intensity:"Baja",duration:9,group:"Parejas",color:"blue",summary:"Una persona observa una postura, cierra los ojos y descubre qué parte del cuerpo ha cambiado de posición.",setup:"Forma parejas separadas; una persona posa y otra observa durante cinco segundos.",rules:["Observa la postura completa sin tocar a la pareja.","Cierra los ojos mientras cambia la posición de una sola parte del cuerpo.","Abre los ojos, señala el cambio y nombra la parte corporal; después intercambiad roles."],variant:"Cambia dos segmentos o reproduce la postura original antes de responder.",observation:"Utiliza vocabulario progresivo: mano, codo, hombro, tobillo, rodilla y cadera.",safety:"Posturas cómodas, estables y sin contacto físico.",image:"images/games/223-foto-corporal.webp"},
{id:224,type:"Imagen corporal",categories:["Esquema corporal","Juegos cooperativos"],title:"El puzle del cuerpo gigante",cycle:"1.º ciclo",goals:["Imagen corporal","Cooperación"],material:"Material específico",intensity:"Baja",duration:14,group:"Equipos de 5",color:"green",summary:"Cada equipo construye en el suelo una figura humana gigante colocando y relacionando sus diferentes segmentos.",setup:"Entrega tarjetas grandes con cabeza, tronco, brazos, manos, piernas y pies, además de cuerdas cortas.",rules:["Ordenad las piezas para formar una figura humana completa.","Unid cada segmento en la posición correspondiente con las cuerdas en el suelo.","Al terminar, nombrad las partes desde la cabeza hasta los pies."],variant:"Construye la figura de perfil, en movimiento o con una postura deportiva.",observation:"Las piezas pueden llevar dibujos, pictogramas o texturas para facilitar el reconocimiento.",safety:"Todo el material permanece en el suelo y se camina alrededor del puzle.",image:"images/games/224-puzle-cuerpo.webp"},
{id:225,type:"Esquema corporal",categories:["Imagen corporal","Juegos motrices"],title:"Los mandos del robot",cycle:"1.º ciclo",goals:["Esquema corporal","Movilidad"],material:"Sin material",intensity:"Media",duration:10,group:"Gran grupo",color:"orange",summary:"El alumnado mueve articulaciones y segmentos concretos como robots que responden a distintos mandos.",setup:"Distribuye al grupo dejando espacio personal y presenta cuatro órdenes: doblar, estirar, girar y parar.",rules:["Escucha el segmento corporal y el mando: por ejemplo, doblar codos.","Mueve únicamente la zona indicada mientras el resto permanece estable.","Al oír «robot completo», enlaza tres movimientos ya practicados."],variant:"Una persona dirige al grupo o se combinan dos articulaciones de forma simultánea.",observation:"Diferencia articulación y segmento con consignas claras y demostraciones breves.",safety:"Movimientos lentos, sin forzar amplitudes ni realizar giros cervicales completos.",image:"images/games/225-mandos-robot.webp"},
{id:226,type:"Esquema corporal",categories:["Juegos motrices"],title:"El dado de los segmentos",cycle:"1.º ciclo",goals:["Esquema corporal","Creatividad motriz"],material:"Material específico",intensity:"Media",duration:10,group:"Pequeños grupos",color:"yellow",summary:"Dos dados combinan una parte corporal y una acción para crear respuestas motrices variadas.",setup:"Prepara un dado con partes del cuerpo y otro con acciones: tocar, elevar, apoyar, separar, acercar y mover.",rules:["Lanza ambos dados y nombra en voz alta la combinación.","Todo el grupo realiza la acción durante cinco segundos.","La siguiente persona propone una forma segura de interpretarla y vuelve a lanzar."],variant:"Añade un tercer dado con niveles: suelo, medio y alto.",observation:"Acepta soluciones diferentes si respetan la parte corporal y la acción obtenidas.",safety:"Dados blandos, acciones sin impacto y apoyos adaptados a cada participante.",image:"images/games/226-dado-segmentos.webp"},
{id:227,type:"Lateralidad",categories:["Esquema corporal","Coordinación","Juegos motrices"],title:"Cruces de la línea media",cycle:"1.º ciclo",goals:["Lateralidad","Coordinación cruzada"],material:"Material específico",intensity:"Media",duration:10,group:"Individual",color:"blue",summary:"Saquitos situados a ambos lados del cuerpo se recogen con la mano contraria y cruzan la línea media corporal.",setup:"Cada participante se sienta o permanece de pie entre dos aros con tres saquitos en cada lado.",rules:["Recoge con la mano derecha un saquito del aro izquierdo y déjalo en el derecho.","Después utiliza la mano izquierda para trasladar uno desde el lado derecho.","Alterna los cruces sin cambiar los pies de posición."],variant:"Realiza la tarea de rodillas, con objetos de colores o siguiendo una secuencia rítmica.",observation:"Marca las muñecas con pulseras de colores si necesitan una referencia visual.",safety:"Objetos blandos, distancia individual y movimientos controlados del tronco.",image:"images/games/227-linea-media.webp"},
{id:228,type:"Lateralidad",categories:["Coordinación","Juegos motrices","Juegos cooperativos"],title:"Pulseras mensajeras",cycle:"1.º ciclo",goals:["Lateralidad","Orientación"],material:"Material específico",intensity:"Media",duration:11,group:"Parejas",color:"green",summary:"Las pulseras de colores ayudan a reconocer derecha e izquierda al transportar mensajes entre bases laterales.",setup:"Cada participante lleva una pulsera azul en la muñeca derecha y otra amarilla en la izquierda; coloca dos bases por pareja.",rules:["Recoge el mensaje con la mano del color nombrado.","Llévalo a la base situada en ese mismo lado de tu pareja.","Entrega mano con mano y cambia quién envía la consigna."],variant:"Cruza el mensaje al lado contrario o añade pie derecho e izquierdo para tocar una marca antes de entregar.",observation:"Mantén siempre el mismo código de color durante la sesión.",safety:"Mensajes de espuma o tarjetas ligeras y desplazamiento sin carreras máximas.",image:"images/games/228-pulseras-mensajeras.webp"},
{id:229,type:"Coordinación",categories:["Esquema corporal","Juegos motrices"],title:"El globo por segmentos",cycle:"1.º ciclo",goals:["Coordinación óculo-segmentaria","Esquema corporal"],material:"Material específico",intensity:"Baja",duration:10,group:"Individual",color:"orange",summary:"Mantener un globo en el aire tocándolo con las partes corporales que indica una secuencia.",setup:"Entrega un globo o una pelota muy ligera por participante y distribuye al grupo ampliamente.",rules:["Golpea suavemente el globo con la parte corporal nombrada.","Espera una nueva consigna antes del siguiente toque.","Si cae, recógelo y continúa desde el mismo punto de la secuencia."],variant:"Alterna derecha e izquierda o crea secuencias de tres segmentos.",observation:"Puede utilizarse una pelota de playa para reducir la velocidad de caída.",safety:"Material ligero, espacio amplio y prohibido golpear con la cabeza.",image:"images/games/229-globo-segmentos.webp"},
{id:230,type:"Coordinación",categories:["Lateralidad","Juegos motrices"],title:"Dos manos, dos misiones",cycle:"2.º ciclo",goals:["Coordinación bimanual","Atención dividida"],material:"Balones",intensity:"Media",duration:11,group:"Individual",color:"yellow",summary:"Cada mano realiza una tarea diferente: una mantiene un bote controlado y la otra traslada objetos ligeros.",setup:"Prepara estaciones con un balón de bote, tres saquitos y dos cajas próximas.",rules:["Bota el balón con una mano dentro de una marca.","Con la otra, traslada los saquitos de una caja a otra uno a uno.","Detente, cambia las tareas de mano y vuelve a comenzar."],variant:"Sustituye el bote por rodar el balón o trabaja por parejas contando los controles logrados.",observation:"Comienza realizando ambas tareas por separado antes de combinarlas.",safety:"Balones adaptados, cajas próximas y estaciones separadas.",image:"images/games/230-dos-misiones.webp"},
{id:231,type:"Agilidad",categories:["Juegos motrices","Juegos cooperativos"],title:"Sombras perseguidoras",cycle:"2.º ciclo",goals:["Agilidad","Cambios de dirección"],material:"Sin material",intensity:"Alta",duration:10,group:"Parejas",color:"blue",summary:"Una sombra sigue los cambios de dirección de su guía manteniendo siempre una distancia segura, sin llegar a tocarlo.",setup:"Forma parejas y asigna a cada una una zona rectangular amplia.",rules:["La guía se desplaza dentro de la zona con cambios de dirección controlados.","La sombra intenta mantener dos metros de distancia y seguir el mismo recorrido.","A los treinta segundos se detienen, recuperan y cambian los papeles."],variant:"Desplazamiento lateral, recorridos curvos o pausas sorpresa de equilibrio.",observation:"No es una captura: se valora ajustar la trayectoria y conservar la distancia.",safety:"Zonas sin cruces, velocidad moderada y prohibidos los retrocesos rápidos.",image:"images/games/231-sombras-perseguidoras.webp"},
{id:232,type:"Agilidad",categories:["Lateralidad","Juegos motrices"],title:"Los tres carriles",cycle:"2.º ciclo",goals:["Agilidad","Reacción"],material:"Conos",intensity:"Alta",duration:10,group:"Pequeños grupos",color:"green",summary:"El alumnado avanza cambiando entre tres carriles paralelos según señales, sin repetir un slalom ni cruzarse con otros recorridos.",setup:"Marca calles con tres carriles anchos y paralelos; sitúa una persona cada vez en cada calle.",rules:["Avanza por el carril central con pasos cortos.","Ante la señal derecha o izquierda, cambia al carril correspondiente y continúa.","Frena dentro de la zona final y regresa caminando por fuera."],variant:"Utiliza colores, palmadas o secuencias de dos cambios consecutivos.",observation:"Trabaja primero los cambios andando y aumenta después la velocidad.",safety:"Carriles anchos, una persona por calle y espacio amplio de frenada.",image:"images/games/232-tres-carriles.webp"},
{id:233,type:"Equilibrio",categories:["Esquema corporal","Juegos cooperativos"],title:"El museo de los apoyos",cycle:"1.º ciclo",goals:["Equilibrio","Conciencia corporal"],material:"Sin material",intensity:"Baja",duration:10,group:"Equipos de 4",color:"orange",summary:"Los equipos crean esculturas estables que deben sumar un número exacto de apoyos sobre el suelo.",setup:"Distribuye equipos por zonas y prepara tarjetas con números de cuatro a diez.",rules:["Extraed una tarjeta y acordad una escultura conjunta con ese total de apoyos.","Mantened la figura durante tres segundos sin cargar peso sobre otra persona.","Contad los apoyos en voz alta y modificad la figura si es necesario."],variant:"Exige al menos una mano, un pie o una rodilla, o construye figuras individuales.",observation:"Un apoyo es cada zona corporal propia que contacta directamente con el suelo.",safety:"Sin subirse, levantar o sostener el peso de compañeros; figuras bajas y cómodas.",image:"images/games/233-museo-apoyos.webp"},
{id:234,type:"Equilibrio",categories:["Juegos cooperativos","Coordinación"],title:"La balanza compartida",cycle:"2.º ciclo",goals:["Equilibrio","Cooperación"],material:"Sin material",intensity:"Baja",duration:9,group:"Parejas",color:"yellow",summary:"Dos personas coordinan cambios lentos de peso y posiciones de equilibrio utilizando solo contacto ligero de las palmas.",setup:"Coloca parejas frente a frente, con pies separados y palmas próximas; acuerdan si desean contacto.",rules:["Apoya suavemente las palmas sin agarrar ni empujar.","Una persona desplaza lentamente el peso hacia un lado y la otra acompaña el movimiento.","Volved al centro, probad el otro lado y cambiad quién inicia."],variant:"Sin contacto, mantened las palmas separadas a pocos centímetros o elevad un talón.",observation:"La alternativa sin contacto permite la misma coordinación visual y postural.",safety:"Presión mínima, pies en el suelo y parada inmediata si aparece inestabilidad.",image:"images/games/234-balanza-compartida.webp"},
{id:235,type:"Imagen corporal",categories:["Esquema corporal","Juegos cooperativos"],title:"Retrato por instrucciones",cycle:"2.º ciclo",goals:["Imagen corporal","Comunicación"],material:"Material específico",intensity:"Baja",duration:11,group:"Parejas",color:"blue",summary:"Una persona describe una postura representada en una tarjeta y su pareja intenta construirla sin ver el modelo.",setup:"Prepara tarjetas con posturas sencillas y coloca a las parejas espalda con espalda, sin contacto.",rules:["Describe la posición de cada segmento sin mostrar la tarjeta ni hacer la postura.","La pareja escucha y construye su propio retrato corporal.","Comprobad el resultado juntos y cambiad los papeles."],variant:"Limita el vocabulario, añade orientación derecha e izquierda o dibuja nuevas tarjetas.",observation:"Valora la precisión del lenguaje corporal más que una copia perfecta.",safety:"Solo posturas cómodas, estables y sin equilibrios elevados.",image:"images/games/235-retrato-instrucciones.webp"},
{id:236,type:"Imagen corporal",categories:["Esquema corporal","Vuelta a la calma"],title:"El mapa de sensaciones",cycle:"2.º ciclo",goals:["Imagen corporal","Conciencia corporal"],material:"Material específico",intensity:"Baja",duration:9,group:"Individual",color:"green",summary:"Después de una acción breve, cada participante identifica en una silueta dónde percibe respiración, calor, tensión o movimiento.",setup:"Entrega una silueta corporal reutilizable y fichas de colores; prepara tres acciones suaves.",rules:["Realiza durante veinte segundos la acción propuesta.","Detente, escucha tu cuerpo y coloca una ficha sobre la zona donde notes más la sensación indicada.","Compara tus propios mapas tras respirar, caminar y mantener una postura."],variant:"Trabaja por parejas explicando el mapa sin juzgar respuestas o utiliza pictogramas de sensaciones.",observation:"No existen respuestas correctas: cada persona percibe su cuerpo de manera diferente.",safety:"Acciones suaves, respiración natural y sin realizar comparaciones corporales entre alumnos.",image:"images/games/236-mapa-sensaciones.webp"},
{id:237,type:"Esquema corporal",categories:["Coordinación","Juegos cooperativos"],title:"Cadena de articulaciones",cycle:"1.º ciclo",goals:["Esquema corporal","Memoria motriz"],material:"Sin material",intensity:"Baja",duration:10,group:"Pequeños grupos",color:"orange",summary:"Cada participante añade a una cadena un movimiento de una articulación diferente y el grupo reproduce la secuencia completa.",setup:"Forma círculos de cinco o seis con espacio para mover brazos y piernas.",rules:["La primera persona mueve una articulación y la nombra.","La siguiente repite el gesto anterior y añade otro de una zona diferente.","La cadena continúa; si se olvida un gesto, el grupo ayuda y vuelve a empezar desde ese punto."],variant:"Asocia un sonido a cada articulación o realiza la cadena de abajo arriba.",observation:"Limita la cadena a cuatro o cinco acciones en los primeros cursos.",safety:"Movimientos pequeños, sin rebotes ni amplitudes forzadas.",image:"images/games/237-cadena-articulaciones.webp"},
{id:238,type:"Esquema corporal",categories:["Coordinación","Juegos motrices"],title:"La pelota exploradora",cycle:"1.º ciclo",goals:["Esquema corporal","Manipulación"],material:"Balones",intensity:"Baja",duration:10,group:"Individual",color:"yellow",summary:"Una pelota blanda viaja alrededor, por encima y por debajo del cuerpo siguiendo recorridos corporales concretos.",setup:"Entrega una pelota pequeña y blanda a cada participante y deja espacio individual.",rules:["Pasa la pelota alrededor de la cintura sin que caiga.","Continúa alrededor de una pierna y después dibuja un círculo por encima de la cabeza.","Termina pasándola bajo ambas rodillas y cambia el sentido del recorrido."],variant:"Realiza la secuencia sentado, de rodillas o por parejas con entrega al completar cada vuelta.",observation:"Trabaja despacio y nombra las zonas que recorre la pelota.",safety:"Pelotas blandas, sin lanzamientos y separación amplia.",image:"images/games/238-pelota-exploradora.webp"},
{id:239,type:"Lateralidad",categories:["Percepción espacial","Juegos cooperativos"],title:"Pilotos derecha-izquierda",cycle:"2.º ciclo",goals:["Lateralidad","Orientación espacial"],material:"Conos",intensity:"Media",duration:12,group:"Parejas",color:"blue",summary:"Una persona guía verbalmente a su piloto por un recorrido abierto utilizando derecha, izquierda, delante y atrás.",setup:"Monta recorridos amplios con conos; el piloto mantiene los ojos abiertos y la pareja camina fuera de la calle.",rules:["La guía utiliza únicamente indicaciones espaciales acordadas.","El piloto avanza caminando y decide cada giro según la instrucción.","Al terminar, revisan los giros y cambian los papeles."],variant:"Añade pulseras de colores, transporta un objeto o permite dos instrucciones encadenadas.",observation:"Se mantiene la visión para centrar la tarea en lateralidad y no en confianza a ciegas.",safety:"Recorridos sin obstáculos, siempre caminando y sin tocar ni empujar al piloto.",image:"images/games/239-pilotos-laterales.webp"},
{id:240,type:"Lateralidad",categories:["Coordinación","Juegos motrices"],title:"Esquinas cruzadas",cycle:"1.º ciclo",goals:["Lateralidad","Coordinación cruzada"],material:"Conos",intensity:"Media",duration:9,group:"Individual",color:"green",summary:"Desde una marca central se relacionan mano y pie contrarios con cuatro esquinas de colores.",setup:"Crea estaciones con una cruz central y cuatro marcas diagonales de colores.",rules:["Mantén un pie sobre el centro.","Toca la esquina señalada con la mano contraria a ese lado.","Regresa al centro y alcanza otra esquina con el pie contrario, sin apoyar las manos."],variant:"Sigue secuencias de dos colores o realiza la tarea desde cuadrupedia.",observation:"Empieza con pocas consignas y verbaliza derecha e izquierda antes de actuar.",safety:"Marcas antideslizantes, alcances cortos y una persona por estación.",image:"images/games/240-esquinas-cruzadas.webp"},
{id:241,type:"Coordinación",categories:["Lateralidad","Juegos motrices"],title:"Pañuelos cruzados",cycle:"2.º ciclo",goals:["Coordinación óculo-manual","Lateralidad"],material:"Material específico",intensity:"Media",duration:10,group:"Individual",color:"orange",summary:"Dos pañuelos ligeros se lanzan y reciben con patrones cruzados que permiten observar cada trayectoria.",setup:"Entrega dos pañuelos de distinto color por participante y distribuye zonas individuales.",rules:["Lanza un pañuelo con cada mano a poca altura.","Atrapa cada color con la misma mano durante los primeros intentos.","Después cruza las recepciones: mano derecha recibe el pañuelo lanzado por la izquierda y viceversa."],variant:"Lanza de forma alterna, añade una palmada o trabaja con un solo pañuelo.",observation:"Los pañuelos caen lentamente y facilitan anticipar la recepción.",safety:"Material muy ligero, lanzamientos bajos y amplia separación.",image:"images/games/241-panuelos-cruzados.webp"},
{id:242,type:"Coordinación",categories:["Ritmo y percepción temporal","Juegos cooperativos","Juegos con balón"],title:"Rodadas con compás",cycle:"1.º ciclo",goals:["Coordinación","Ritmo"],material:"Balones",intensity:"Baja",duration:10,group:"Parejas",color:"yellow",summary:"La pareja rueda una pelota siguiendo un compás de palmadas y cambia la mano de envío según el ritmo.",setup:"Coloca parejas sentadas frente a frente con una pelota blanda y distancia corta.",rules:["Da dos palmadas y rueda la pelota con ambas manos.","La pareja recibe, repite el compás y devuelve.","Cuando el ritmo sea estable, alternad rodada con mano derecha e izquierda."],variant:"Utiliza compases de una o tres palmadas o amplía ligeramente la distancia.",observation:"La pelota siempre rueda; no se lanza ni se bota.",safety:"Pelota blanda, espacio despejado y piernas colocadas fuera de la trayectoria.",image:"images/games/242-rodadas-compas.webp"},
{id:243,type:"Agilidad",categories:["Coordinación","Juegos motrices"],title:"Atrapa antes del segundo bote",cycle:"2.º ciclo",goals:["Agilidad","Reacción"],material:"Balones",intensity:"Alta",duration:9,group:"Parejas",color:"blue",summary:"Una pelota soltada por la pareja activa una salida breve para capturarla antes de que complete su segundo bote.",setup:"Forma parejas con una pelota de bote; una persona espera preparada a dos o tres metros.",rules:["La persona que sostiene la pelota la deja caer sin avisar ni lanzarla.","La compañera reacciona e intenta atraparla antes del segundo bote.","Devuelve caminando, alterna distancias y cambia de función tras cinco intentos."],variant:"Salida lateral, sentado o de espaldas girando al oír el primer bote.",observation:"Ajusta la distancia para que haya éxito frecuente.",safety:"Una pareja por calle, pelota controlada y frenada antes de devolver.",image:"images/games/243-segundo-bote.webp"},
{id:244,type:"Agilidad",categories:["Percepción espacial","Juegos motrices"],title:"El rebote escapista",cycle:"2.º ciclo",goals:["Agilidad","Anticipación"],material:"Balones",intensity:"Alta",duration:10,group:"Pequeños grupos",color:"green",summary:"Una pelota de espuma rebota de forma imprevisible dentro de una zona y el jugador ajusta su trayectoria para interceptarla.",setup:"Delimita cuadrados amplios; una persona docente o compañera hace botar una pelota de espuma desde fuera.",rules:["Entra en la zona cuando la pelota realiza el primer bote.","Sigue su trayectoria y atrápala antes de que salga del cuadrado.","Sal por un lateral, entrega la pelota y deja entrar a la siguiente persona."],variant:"Cambia el tamaño de la zona o utiliza una pelota con bote más lento.",observation:"No se compite entre jugadores; cada intento tiene una única persona activa.",safety:"Pelota blanda, cuadrado libre y lanzador siempre fuera de la trayectoria.",image:"images/games/244-rebote-escapista.webp"},
{id:245,type:"Equilibrio",categories:["Lateralidad","Coordinación"],title:"El reloj del equilibrio",cycle:"2.º ciclo",goals:["Equilibrio","Control postural"],material:"Conos",intensity:"Baja",duration:10,group:"Individual",color:"orange",summary:"Sobre un pie central, la pierna libre toca marcas distribuidas como horas alrededor del cuerpo sin perder estabilidad.",setup:"Coloca una base central antideslizante y seis marcas próximas alrededor de cada estación.",rules:["Apoya un pie en el centro y mantén la mirada al frente.","Toca con el pie libre la marca indicada y vuelve sin apoyarlo.","Tras tres señales, descansa y cambia la pierna de apoyo."],variant:"Sigue una secuencia de colores o toca con una mano manteniendo ambos pies apoyados.",observation:"Acerca las marcas para adaptar la amplitud individual.",safety:"Superficie estable, alcances cortos y apoyo permitido cuando se pierde el control.",image:"images/games/245-reloj-equilibrio.webp"},
{id:246,type:"Equilibrio",categories:["Esquema corporal","Juegos motrices"],title:"Cambio de base",cycle:"1.º ciclo",goals:["Equilibrio","Control corporal"],material:"Aros",intensity:"Baja",duration:9,group:"Individual",color:"yellow",summary:"Las señales transforman lentamente la base de sustentación: cuatro, tres, dos o un apoyo, manteniendo una postura estable.",setup:"Sitúa al alumnado dentro de aros separados y prepara tarjetas con uno, dos, tres y cuatro puntos.",rules:["Comienza con manos y pies dentro del aro.","Al mostrar una tarjeta, cambia hasta dejar en el suelo ese número de apoyos.","Mantén la postura tres segundos y vuelve a cuatro apoyos antes de otra señal."],variant:"Indica qué apoyos deben permanecer o enlaza dos cambios sin levantarse.",observation:"Permite rodillas, manos, pies o asiento según la solución elegida.",safety:"Aros planos, transiciones lentas y ninguna postura invertida.",image:"images/games/246-cambio-base.webp"},
{id:247,type:"Imagen corporal",categories:["Percepción espacial","Juegos motrices"],title:"Formas dentro del marco",cycle:"1.º ciclo",goals:["Imagen corporal","Noción de tamaño"],material:"Cuerdas",intensity:"Baja",duration:10,group:"Individual",color:"blue",summary:"El cuerpo explora formas grandes, pequeñas, anchas y estrechas dentro de marcos de cuerda de distinto tamaño.",setup:"Forma cuadrados y círculos amplios con cuerdas colocadas en el suelo, uno por participante.",rules:["Entra caminando en un marco libre.","Representa con tu cuerpo la cualidad indicada: grande, pequeño, ancho, estrecho, alto o bajo.","Observa cuánto espacio ocupas y cambia de marco a la señal."],variant:"Combina dos cualidades o representa animales y objetos con ese tamaño.",observation:"No se comparan cuerpos; se comparan las formas creadas por una misma persona.",safety:"Cuerdas siempre planas, marcos separados y cambios caminando.",image:"images/games/247-formas-marco.webp"},
{id:248,type:"Imagen corporal",categories:["Esquema corporal","Creatividad","Juegos cooperativos"],title:"Autorretrato con material",cycle:"1.º ciclo",goals:["Imagen corporal","Representación"],material:"Aros",intensity:"Baja",duration:14,group:"Parejas",color:"green",summary:"Cada pareja crea en el suelo un autorretrato corporal con aros, cuerdas y saquitos y después reproduce su postura.",setup:"Entrega a cada pareja dos aros, tres cuerdas cortas y varios saquitos blandos.",rules:["Construid una figura humana usando el material únicamente sobre el suelo.","Decidid qué elemento representa cada parte corporal.","Una persona adopta la postura del retrato y la otra comprueba semejanzas antes de cambiar."],variant:"Retrato en movimiento, sentado o realizando un deporte.",observation:"La figura puede ser simbólica; importa explicar las decisiones tomadas.",safety:"Material plano, sin enrollar cuerdas en el cuerpo y posturas cómodas.",image:"images/games/248-autorretrato-material.webp"},
{id:249,type:"Esquema corporal",categories:["Coordinación","Juegos cooperativos"],title:"Eco corporal inverso",cycle:"2.º ciclo",goals:["Esquema corporal","Memoria motriz"],material:"Sin material",intensity:"Baja",duration:10,group:"Pequeños grupos",color:"orange",summary:"Un guía toca o mueve varias partes de su propio cuerpo y el grupo reproduce la secuencia en orden inverso.",setup:"Forma círculos de cuatro o cinco y deja una persona guía en cada ronda.",rules:["El guía muestra una secuencia de tres acciones sobre su propio cuerpo.","El grupo observa en silencio y la reproduce comenzando por la última.","Comprobad juntos el orden y cambiad de guía."],variant:"Aumenta a cuatro acciones, añade derecha e izquierda o acompaña cada gesto con un sonido.",observation:"Empieza con segmentos muy diferenciados y ritmo lento.",safety:"Sin tocar a otras personas ni realizar movimientos articulares forzados.",image:"images/games/249-eco-inverso.webp"},
{id:250,type:"Esquema corporal",categories:["Coordinación","Juegos motrices"],title:"El saquito viajero",cycle:"1.º ciclo",goals:["Esquema corporal","Control de objetos"],material:"Material específico",intensity:"Baja",duration:9,group:"Individual",color:"yellow",summary:"Un saquito blando cambia de lugar sobre el propio cuerpo siguiendo consignas de apoyo y transporte.",setup:"Entrega un saquito blando por persona y distribuye al alumnado en marcas separadas.",rules:["Coloca el saquito en la parte corporal indicada.","Camina tres pasos intentando mantenerlo estable.","Detente, pásalo con las manos a otra zona y continúa con la nueva consigna."],variant:"Trabaja sentado, en cuadrupedia o enlaza hombro, antebrazo, muslo y empeine.",observation:"Evita zonas donde el objeto pueda bloquear la visión.",safety:"Saquitos ligeros, desplazamiento lento y recogida sin carreras.",image:"images/games/250-saquito-viajero.webp"},
{id:251,type:"Lateralidad",categories:["Coordinación","Juegos motrices"],title:"Pasos del lado guía",cycle:"1.º ciclo",goals:["Lateralidad","Desplazamiento lateral"],material:"Material específico",intensity:"Media",duration:10,group:"Individual",color:"blue",summary:"Una cinta de color indica qué lado del cuerpo inicia cada secuencia de pasos laterales.",setup:"Coloca bandas planas paralelas en el suelo y una pulsera de color en cada muñeca.",rules:["Sitúate de frente a la banda sin pisarla.","Si se muestra el color derecho, cruza primero con pie derecho; si aparece el izquierdo, inicia con ese pie.","Completa cuatro pasos laterales y regresa caminando."],variant:"Añade brazos del mismo lado, cruces por delante o una pausa de equilibrio.",observation:"Practica lentamente la diferencia entre pie que inicia y dirección del desplazamiento.",safety:"Bandas planas, calles separadas y sin cruzar los pies a velocidad alta.",image:"images/games/251-lado-guia.webp"},
{id:252,type:"Lateralidad",categories:["Coordinación","Juegos cooperativos","Juegos con balón"],title:"Balón al lado nombrado",cycle:"2.º ciclo",goals:["Lateralidad","Recepción"],material:"Balones",intensity:"Media",duration:10,group:"Parejas",color:"green",summary:"La pareja rueda el balón hacia un lado concreto y quien recibe lo controla con la mano o el pie correspondiente.",setup:"Forma parejas frente a frente y marca a cada receptor una zona derecha y otra izquierda.",rules:["Nombra un lado y rueda el balón hacia esa zona.","Quien recibe controla con la mano o el pie del mismo lado.","Devuelve por el centro, alterna los lados y cambia quién da la consigna."],variant:"Control con lado contrario, dos señales seguidas o mayor distancia.",observation:"Utiliza pulseras o marcas de color como apoyo visual estable.",safety:"Balón blando siempre rodado y distancia suficiente entre parejas.",image:"images/games/252-balon-lado.webp"},
{id:253,type:"Coordinación",categories:["Juegos cooperativos","Juegos motrices"],title:"Aros rodantes por puertas",cycle:"2.º ciclo",goals:["Coordinación óculo-manual","Control de fuerza"],material:"Aros",intensity:"Media",duration:12,group:"Parejas",color:"orange",summary:"La pareja hace rodar un aro para que atraviese una puerta y llegue controlado a la persona receptora.",setup:"Coloca parejas a ambos lados de una puerta ancha de conos con un aro resistente y ligero.",rules:["Impulsa el aro desde el lateral para que ruede sin lanzarlo.","La pareja lo detiene con ambas manos después de cruzar la puerta.","Cada tres envíos, modifica ligeramente la distancia o la anchura."],variant:"Dos puertas consecutivas, cambio de mano impulsora o recorrido curvo muy amplio.",observation:"Practica primero cómo acompañar y frenar el aro sin meter manos entre aro y suelo.",safety:"Aros separados, rodados a baja velocidad y nunca dirigidos hacia las piernas.",image:"images/games/253-aros-puertas.webp"},
{id:254,type:"Coordinación",categories:["Ritmo y percepción temporal","Juegos motrices"],title:"Pies al pulso, manos al eco",cycle:"2.º ciclo",goals:["Coordinación disociada","Ritmo"],material:"Sin material",intensity:"Media",duration:9,group:"Gran grupo",color:"yellow",summary:"Los pies mantienen un pulso regular mientras las manos reproducen una secuencia de palmadas diferente.",setup:"Distribuye al grupo en semicírculo con espacio individual y marca un pulso lento con voz o instrumento.",rules:["Alterna pasos en el sitio siguiendo el pulso constante.","Escucha una secuencia corta de palmadas sin detener los pies.","Repite el eco con las manos mientras los pasos siguen al mismo ritmo."],variant:"Cambia el tempo, usa muslos y palmas o trabaja por parejas.",observation:"Practica primero pies y manos por separado antes de combinarlos.",safety:"Pasos bajos, sin saltos y separación suficiente para mover brazos.",image:"images/games/254-pulso-eco.webp"},
{id:255,type:"Agilidad",categories:["Coordinación","Juegos motrices"],title:"Salva el aro rodante",cycle:"2.º ciclo",goals:["Agilidad","Anticipación"],material:"Aros",intensity:"Alta",duration:10,group:"Parejas",color:"blue",summary:"Una persona hace rodar un aro por una calle y la compañera ajusta su carrera para detenerlo antes de la línea final.",setup:"Prepara calles anchas con una línea de salida y otra de rescate; un aro por pareja.",rules:["Haz rodar el aro desde la salida con velocidad moderada.","La compañera sale después y lo detiene con ambas manos antes de la línea.","Regresad caminando por fuera y cambiad las funciones."],variant:"Salida lateral, calle más corta o aro rodado con la otra mano.",observation:"Ajusta la fuerza para que el reto sea alcanzable y no una carrera máxima.",safety:"Una pareja por calle, aro en buen estado y frenada amplia.",image:"images/games/255-salva-aro.webp"},
{id:256,type:"Agilidad",categories:["Reacción","Juegos motrices"],title:"El pañuelo sorpresa",cycle:"1.º ciclo",goals:["Agilidad","Velocidad de reacción"],material:"Material específico",intensity:"Media",duration:9,group:"Parejas",color:"green",summary:"Un pañuelo se suelta desde distintas alturas y la pareja reacciona para atraparlo antes de que toque el suelo.",setup:"Forma parejas; una sostiene un pañuelo ligero mientras la otra espera a corta distancia en posición preparada.",rules:["Suelta el pañuelo sin empujarlo ni avisar.","La pareja intenta atraparlo antes de que llegue al suelo.","Tras cinco intentos, cambiad de función y modificad ligeramente la distancia."],variant:"Salida sentado, de lado o tras una palmada previa.",observation:"El material lento permite trabajar reacción con bajo riesgo.",safety:"Zona individual, distancia corta y desplazamiento sin lanzarse al suelo.",image:"images/games/256-panuelo-sorpresa.webp"},
{id:257,type:"Equilibrio",categories:["Esquema corporal","Juegos motrices"],title:"El ascensor del equilibrio",cycle:"2.º ciclo",goals:["Equilibrio","Control postural"],material:"Material específico",intensity:"Baja",duration:10,group:"Individual",color:"orange",summary:"El cuerpo sube y baja por niveles —sentado, de rodillas, medio arrodillado y de pie— manteniendo un saquito estable.",setup:"Entrega un saquito blando y una colchoneta fina por participante.",rules:["Comienza sentado con el saquito sobre una mano abierta.","Pasa lentamente por rodillas, medio arrodillado y de pie sin que caiga.","Detente tres segundos en cada planta del ascensor y desciende en orden inverso."],variant:"Saquito sobre el hombro o ambas manos, o detención extra a media altura.",observation:"Permite apoyar la mano libre cuando sea necesario.",safety:"Colchoneta estable, transiciones lentas y espacio individual.",image:"images/games/257-ascensor-equilibrio.webp"},
{id:258,type:"Equilibrio",categories:["Orientación espacial","Juegos motrices"],title:"La isla que gira",cycle:"1.º ciclo",goals:["Equilibrio","Orientación"],material:"Aros",intensity:"Baja",duration:9,group:"Individual",color:"yellow",summary:"Dentro de una isla, el alumnado realiza pequeños giros para terminar estable y orientado hacia una referencia concreta.",setup:"Coloca aros separados y cuatro conos de colores alrededor de cada uno.",rules:["Permanece dentro del aro con los pies cómodamente separados.","Gira con pasos pequeños hasta mirar al color indicado.","Detente, mantén el equilibrio tres segundos y espera otra referencia."],variant:"Giro de un cuarto o media vuelta, ojos en una referencia o final sobre un pie.",observation:"Diferente de girar rápido: se valora la parada estable y la orientación final.",safety:"Giros pequeños, sin saltos y aros completamente planos.",image:"images/games/258-isla-gira.webp"},
{id:259,type:"Imagen corporal",categories:["Percepción espacial","Juegos motrices"],title:"Pasaporte de anchuras",cycle:"1.º ciclo",goals:["Imagen corporal","Estimación corporal"],material:"Picas y conos",intensity:"Baja",duration:10,group:"Individual",color:"blue",summary:"El alumnado estima el espacio que ocupa su cuerpo y elige por qué puerta puede pasar con distintas posturas sin tocarla.",setup:"Construye puertas de varias anchuras y alturas con conos, picas y soportes seguros.",rules:["Observa las puertas antes de moverte y elige una que creas adecuada.","Atraviesa caminando de frente, de lado o agachado según la señal.","Comprueba si tu estimación fue correcta y prueba otra puerta."],variant:"Transporta un balón pegado al cuerpo o compara la misma puerta con dos posturas.",observation:"Se valora ajustar la postura, no pasar por la puerta más pequeña.",safety:"Picas blandas o apoyadas para que caigan fácilmente, sin carreras ni empujones.",image:"images/games/259-pasaporte-anchuras.webp"},
{id:260,type:"Imagen corporal",categories:["Expresión corporal","Juegos cooperativos"],title:"Estatua desde tres miradas",cycle:"2.º ciclo",goals:["Imagen corporal","Representación postural"],material:"Sin material",intensity:"Baja",duration:11,group:"Pequeños grupos",color:"green",summary:"Una estatua mantiene su postura mientras tres observadores descubren cómo cambia su silueta vista de frente, de perfil y desde atrás.",setup:"Forma grupos de cuatro y asigna una marca central para la estatua y tres puntos de observación.",rules:["Crea una postura clara y mantenla durante cinco segundos.","Los observadores se colocan de frente, de perfil y detrás sin tocar a la estatua.","Cada observador reproduce lo que ve; después comparad las tres siluetas y cambiad de función."],variant:"Usa posturas deportivas, emociones o figuras con distintos niveles.",observation:"Ayuda a comprender que el mismo cuerpo ofrece imágenes diferentes según el punto de vista.",safety:"Posturas estables, separación suficiente y desplazamientos caminando.",image:"images/games/260-tres-miradas.webp"},
{id:261,type:"Esquema corporal",categories:["Ritmo y percepción temporal","Juegos motrices"],title:"Semáforo de articulaciones",cycle:"1.º ciclo",goals:["Esquema corporal","Movilidad segmentaria"],material:"Conos",intensity:"Baja",duration:9,group:"Gran grupo",color:"orange",summary:"Los colores regulan el movimiento de una articulación concreta: libre, lento o completamente detenido.",setup:"Prepara señales verde, amarilla y roja y distribuye al grupo con espacio individual.",rules:["Escucha la articulación nombrada: hombros, codos, muñecas, cadera, rodillas o tobillos.","Con verde muévela con amplitud cómoda; con amarillo hazlo muy despacio.","Con rojo congela esa articulación mientras el resto del cuerpo permanece relajado."],variant:"Combina dos articulaciones o asigna un movimiento diferente a cada color.",observation:"Distingue articulaciones de segmentos y evita copiar siempre al compañero.",safety:"Movimientos controlados, sin rebotes ni amplitudes forzadas.",image:"images/games/261-semaforo-articulaciones.webp"},
{id:262,type:"Esquema corporal",categories:["Juegos cooperativos","Percepción espacial"],title:"Puentes y túneles del cuerpo",cycle:"1.º ciclo",goals:["Esquema corporal","Apoyos corporales"],material:"Pelotas",intensity:"Baja",duration:11,group:"Parejas",color:"yellow",summary:"Una persona crea puentes y túneles con distintos apoyos para que su pareja haga rodar una pelota por debajo o alrededor.",setup:"Forma parejas separadas y entrega una pelota blanda pequeña a cada una.",rules:["Construye un puente estable usando las partes corporales indicadas.","La pareja hace rodar la pelota por el espacio libre sin tocar el cuerpo.","Cambia la forma, nombra los apoyos utilizados e intercambia funciones."],variant:"Crea un túnel sentado, en cuadrupedia o con un brazo y una pierna como límites.",observation:"La forma debe permitir reconocer qué segmentos sostienen el cuerpo.",safety:"Pelota siempre rodada, apoyos cómodos y ninguna persona pasa bajo otra.",image:"images/games/262-puentes-tuneles.webp"},
{id:263,type:"Lateralidad",categories:["Orientación espacial","Juegos motrices"],title:"Flechas que cambian de lado",cycle:"1.º ciclo",goals:["Lateralidad","Orientación"],material:"Material específico",intensity:"Media",duration:10,group:"Individual",color:"blue",summary:"Las flechas indican hacia dónde avanzar, pero una pulsera señala qué pie o mano debe iniciar cada acción.",setup:"Coloca flechas planas formando caminos y entrega pulseras de distinto color para derecha e izquierda.",rules:["Sigue la dirección de la flecha sin confundirla con el lado del cuerpo.","Inicia cada paso con el lado indicado por la tarjeta de color.","Al llegar a una estación, toca la marca con la mano del mismo lado y continúa."],variant:"Usa mano contraria, cambia la orientación inicial o recorre el camino hacia atrás lentamente.",observation:"Trabaja por separado dirección espacial y lado corporal antes de combinarlos.",safety:"Flechas antideslizantes, recorridos separados y velocidad moderada.",image:"images/games/263-flechas-lado.webp"},
{id:264,type:"Lateralidad",categories:["Percepción espacial","Juegos cooperativos"],title:"La brújula lateral",cycle:"2.º ciclo",goals:["Lateralidad","Cambio de referencia"],material:"Conos",intensity:"Media",duration:10,group:"Parejas",color:"green",summary:"Tras orientarse hacia distintos puntos, cada jugador localiza rápidamente qué objeto queda a su derecha y cuál a su izquierda.",setup:"Sitúa cuatro conos de colores alrededor de cada pareja y una marca central orientable.",rules:["Colócate en el centro mirando al color que diga tu pareja.","Sin girarte, señala el cono que ahora queda a tu derecha y después el de tu izquierda.","Comprueba, cambia la orientación y alterna quién da las consignas."],variant:"Toca el cono con la mano correspondiente o realiza un cuarto de giro antes de responder.",observation:"La derecha y la izquierda corporales se mantienen aunque cambien las referencias del espacio.",safety:"Conos cercanos, desplazamientos caminando y una pareja por estación.",image:"images/games/264-brujula-lateral.webp"},
{id:265,type:"Coordinación",categories:["Juegos con balón","Juegos motrices"],title:"Dos pelotas, dos alturas",cycle:"2.º ciclo",goals:["Coordinación bimanual","Disociación"],material:"Balones",intensity:"Media",duration:10,group:"Individual",color:"orange",summary:"Cada mano controla una pelota diferente: una rueda o bota cerca del suelo mientras la otra realiza un lanzamiento corto.",setup:"Entrega una pelota de bote y otra ligera por participante, dejando zonas individuales amplias.",rules:["Bota la pelota grande con una mano a ritmo cómodo.","Con la otra, lanza la pelota ligera por debajo de los ojos y vuelve a recibirla.","Mantén ambas acciones durante cinco segundos, detente y cambia las manos."],variant:"Sustituye el bote por una rodada alrededor del cuerpo o usa un pañuelo ligero.",observation:"Practica cada tarea por separado y acepta ritmos diferentes entre manos.",safety:"Lanzamientos bajos, balones blandos y amplia separación.",image:"images/games/265-dos-pelotas.webp"},
{id:266,type:"Coordinación",categories:["Esquema corporal","Juegos motrices"],title:"Escalera de manos y pies",cycle:"2.º ciclo",goals:["Coordinación global","Secuenciación motriz"],material:"Material específico",intensity:"Media",duration:11,group:"Individual",color:"yellow",summary:"Una escalera dibujada en el suelo propone secuencias que combinan apoyos de manos y pies sin posiciones invertidas.",setup:"Coloca escaleras de coordinación planas y tarjetas con secuencias sencillas de manos y pies.",rules:["Observa la tarjeta antes de entrar en la escalera.","Coloca manos y pies en los cuadros siguiendo el orden marcado.","Sal caminando, comprueba la secuencia y repítela con mayor fluidez."],variant:"Alterna lateralmente, cambia el primer apoyo o crea una secuencia para un compañero.",observation:"Prioriza precisión y continuidad antes que velocidad.",safety:"Escalera plana, manos apoyadas solo con tronco bajo y distancia entre participantes.",image:"images/games/266-escalera-manos-pies.webp"},
{id:267,type:"Agilidad",categories:["Reacción","Percepción espacial"],title:"Puertas relámpago",cycle:"2.º ciclo",goals:["Agilidad","Cambio de dirección"],material:"Conos",intensity:"Alta",duration:10,group:"Pequeños grupos",color:"blue",summary:"Desde una zona central, el jugador reacciona a una señal y atraviesa la puerta de color que acaba de abrirse.",setup:"Marca un centro y cuatro puertas de colores; un compañero controla cada pareja de puertas con una pica blanda en el suelo.",rules:["Espera en movimiento suave dentro del centro.","Cuando una puerta se abra y aparezca su color, cambia de dirección y atraviésala.","Regresa por fuera caminando y ocupa el final de la fila."],variant:"Abre dos puertas y nombra una, salida sentado o regreso por un color distinto.",observation:"Las señales deben ser claras y el recorrido breve para trabajar reacción, no resistencia.",safety:"Picas siempre a ras del suelo, puertas amplias y un corredor cada vez.",image:"images/games/267-puertas-relampago.webp"},
{id:268,type:"Agilidad",categories:["Juegos cooperativos","Juegos motrices"],title:"Rescate de conos",cycle:"1.º ciclo",goals:["Agilidad","Frenada y aceleración"],material:"Conos",intensity:"Alta",duration:9,group:"Pequeños grupos",color:"green",summary:"El equipo rescata conos tumbados de uno en uno, alternando salidas cortas, frenadas y regresos controlados.",setup:"Distribuye conos tumbados en una zona y sitúa equipos pequeños detrás de líneas separadas.",rules:["Sale una persona, levanta un único cono y regresa por el mismo carril.","Choca la palma de la siguiente para darle la salida.","Terminada la ronda, contad cuántos conos habéis rescatado entre todos y recolocadlos."],variant:"Transporta el cono hasta la base, cambia la forma de desplazamiento o rescata por colores.",observation:"No hay equipo eliminado; se busca mejorar la organización y el control de las frenadas.",safety:"Carriles amplios, conos flexibles y prohibido deslizarse o lanzarse al suelo.",image:"images/games/268-rescate-conos.webp"},
{id:269,type:"Equilibrio",categories:["Orientación espacial","Esquema corporal"],title:"El faro sobre la roca",cycle:"2.º ciclo",goals:["Equilibrio","Estabilidad visual"],material:"Colchonetas",intensity:"Baja",duration:10,group:"Individual",color:"orange",summary:"Sobre una base estable, el cuerpo mantiene el equilibrio mientras la cabeza y los brazos localizan señales situadas alrededor.",setup:"Coloca colchonetas finas o marcas firmes y varios conos de colores a distintas alturas alrededor.",rules:["Adopta una posición estable sobre la roca con un pie o dos apoyos estrechos.","Gira solo la cabeza hacia el color nombrado y señala con el brazo como un faro.","Vuelve al frente antes de buscar la siguiente señal y cambia el apoyo."],variant:"Sigue dos colores consecutivos o realiza el ejercicio en medio arrodillado.",observation:"El reto procede del movimiento de cabeza y brazos, no de una superficie inestable.",safety:"Base firme, apoyo permitido en cualquier momento y movimientos lentos.",image:"images/games/269-faro-roca.webp"},
{id:270,type:"Equilibrio",categories:["Juegos cooperativos","Percepción espacial"],title:"Huellas viajeras",cycle:"1.º ciclo",goals:["Equilibrio dinámico","Cooperación"],material:"Material específico",intensity:"Baja",duration:12,group:"Parejas",color:"yellow",summary:"La pareja cruza una distancia usando tres huellas móviles, trasladando la que queda atrás sin pisar fuera.",setup:"Entrega a cada pareja tres bases planas antideslizantes y marca una salida y una llegada próximas.",rules:["Cada persona ocupa una huella y la tercera queda libre delante.","Avanzad por turnos y pasad hacia delante la huella que quede vacía atrás.","Si alguien pisa fuera, recuperad el equilibrio y continuad desde la última posición estable."],variant:"Cruce individual con dos huellas, recorrido curvo o transporte de un saquito.",observation:"La comunicación y la colocación de la próxima base son parte del juego.",safety:"Bases completamente planas, pasos cortos y prohibido saltar entre huellas.",image:"images/games/270-huellas-viajeras.webp"}
];
